FINAL = ["Скайрим вечен?", "Скайрим играл?", "Ласт оф ас 2 хорошая игра?",
"Киберпанк 2077 великая игра", "Грангер лучший персонаж", "Ты кто?",
"Скажи что-нибудь как истинный дтфер", "Стоит покупать новый айфон?",
"Ведьмак 3 переоценён", "Почему люди любят Дарк Соулс?", "Как дела?", "Что думаешь о Minecraft?"]


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("output", type=Path)
    a = ap.parse_args()
    a.output.mkdir(parents=True, exist_ok=True)
    dev = [{"id": f"{group}-{index:02d}", "category": group, "prompt": text,
            "split": "development"} for group, texts in GROUPS.items() for index, text in enumerate(texts)]
    final = [{"id": f"human-{index:02d}", "category": "final_human", "prompt": text,
              "split": "final"} for index, text in enumerate(FINAL)]
    for name, data in [("eval_stage3_dev.json", dev), ("eval_stage3_final.json", final),
                       ("eval_stage3_exclude.json", dev + final)]:
        (a.output / name).write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Frozen development prompts={len(dev)}, final human prompts={len(final)}")


if __name__ == "__main__":
    main()
